import AVFoundation
import Observation

/// Looping tracks (generated by `scripts/generate_music.py`) that play while a puzzle is in progress.
@MainActor
@Observable
final class BackgroundMusic {
    static let shared = BackgroundMusic()

    enum Track: String, CaseIterable, Identifiable {
        case off
        case calm = "calm-loop"
        case rain = "rain-loop"
        case musicBox = "music-box-loop"
        case night = "night-loop"
        case meadow = "meadow-loop"

        var id: String { rawValue }

        var title: String {
            switch self {
            case .off: L10n.Game.musicOff
            case .calm: L10n.Game.musicCalm
            case .rain: L10n.Game.musicRain
            case .musicBox: L10n.Game.musicBox
            case .night: L10n.Game.musicNight
            case .meadow: L10n.Game.musicMeadow
            }
        }
    }

    private static let volume: Float = 0.5
    private static let trackKey = "pz.music.track"

    /// The player's pick, remembered across launches.
    var track: Track {
        didSet {
            UserDefaults.standard.set(track.rawValue, forKey: Self.trackKey)
            let wasPlaying = player?.isPlaying == true
            player?.stop()
            player = nil
            if wasPlaying { play() }
        }
    }

    @ObservationIgnored private var player: AVAudioPlayer?
    @ObservationIgnored private var fadeTask: Task<Void, Never>?

    private init() {
        track = UserDefaults.standard.string(forKey: Self.trackKey).flatMap(Track.init(rawValue:)) ?? .calm
    }

    func play() {
        fadeTask?.cancel()
        if player == nil, track != .off, let url = Bundle.module.url(forResource: track.rawValue, withExtension: "m4a") {
            // Ambient: respects the silent switch and mixes with the player's own music.
            try? AVAudioSession.sharedInstance().setCategory(.ambient)
            player = try? AVAudioPlayer(contentsOf: url)
            player?.numberOfLoops = -1
        }
        guard let player else { return }
        if !player.isPlaying { player.volume = 0 }
        player.play()
        player.setVolume(Self.volume, fadeDuration: 2)
    }

    /// Fades out, then pauses so the next puzzle picks up where the melody left off.
    func stop() {
        guard let player, player.isPlaying else { return }
        player.setVolume(0, fadeDuration: 1.5)
        fadeTask = Task {
            try? await Task.sleep(for: .seconds(1.5))
            guard !Task.isCancelled else { return }
            player.pause()
        }
    }
}
